import { describe, it, expect, vi } from 'vitest';
import { ChipBar } from './ChipBar';

const options = ['fiction', 'non-fiction', 'sci-fi'];

describe('ChipBar', () => {
  it('renders a chip for each option', () => {
    render(<ChipBar options={options} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getAllByRole('button')).toHaveLength(3);
  });

  it('renders chip labels matching options', () => {
    render(<ChipBar options={options} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'fiction' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'non-fiction' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'sci-fi' })).toBeInTheDocument();
  });

  it('unselected chip has aria-pressed false', () => {
    render(<ChipBar options={options} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'fiction' })).toHaveAttribute(
      'aria-pressed',
      'false',
    );
  });

  it('selected chip has aria-pressed true', () => {
    render(<ChipBar options={options} selected={['fiction']} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'fiction' })).toHaveAttribute(
      'aria-pressed',
      'true',
    );
  });

  it('clicking an unselected chip calls onSelectionChange with it added', async () => {
    const handleChange = vi.fn();
    render(
      <ChipBar options={options} selected={['sci-fi']} onSelectionChange={handleChange} />,
    );
    await userEvent.click(screen.getByRole('button', { name: 'fiction' }));
    expect(handleChange).toHaveBeenCalledTimes(1);
    expect(handleChange).toHaveBeenCalledWith(expect.arrayContaining(['sci-fi', 'fiction']));
  });

  it('clicking a selected chip calls onSelectionChange with it removed', async () => {
    const handleChange = vi.fn();
    render(
      <ChipBar options={options} selected={['fiction', 'sci-fi']} onSelectionChange={handleChange} />,
    );
    await userEvent.click(screen.getByRole('button', { name: 'fiction' }));
    expect(handleChange).toHaveBeenCalledWith(['sci-fi']);
  });

  it('only the toggled chip changes — other pressed states unchanged', async () => {
    const handleChange = vi.fn();
    render(
      <ChipBar options={options} selected={['sci-fi']} onSelectionChange={handleChange} />,
    );
    await userEvent.click(screen.getByRole('button', { name: 'fiction' }));
    const [nextSelected] = handleChange.mock.calls[0] as [string[]];
    expect(nextSelected).toContain('sci-fi');
  });
});

