import { renderHook, waitFor } from '@testing-library/react';
import { describe, it, expect, vi, afterEach } from 'vitest';
import { useBooks } from './useBooks';
import * as api from '../api';

afterEach(() => {
  vi.restoreAllMocks();
});

describe('useBooks', () => {
  it('starts in loading state with null data and null error', () => {
    const { result } = renderHook(() => useBooks());
    expect(result.current.loading).toBe(true);
    expect(result.current.data).toBeNull();
    expect(result.current.error).toBeNull();
  });

  it('populates data and clears loading after getBooks resolves', async () => {
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(Array.isArray(result.current.data)).toBe(true);
    expect(result.current.error).toBeNull();
  });

  it('data items include id, title, author, status', async () => {
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    const books = result.current.data ?? [];
    if (books.length > 0) {
      const book = books[0];
      expect(book).toHaveProperty('id');
      expect(book).toHaveProperty('title');
      expect(book).toHaveProperty('author');
      expect(book).toHaveProperty('status');
    }
  });

  it('sets error and clears loading when getBooks rejects', async () => {
    const err = new Error('api failure');
    vi.spyOn(api, 'getBooks').mockRejectedValueOnce(err);
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.error).toBe(err);
    expect(result.current.data).toBeNull();
  });

  it('error state does not expose stale data', async () => {
    const err = new Error('api failure');
    vi.spyOn(api, 'getBooks').mockRejectedValueOnce(err);
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.data).toBeNull();
  });
});

